export function getPermissionsByRole(roleType) {
  return RolePermissions[roleType] || RolePermissions[Role.JUNIOR_MEMBER]
}

export function hasPermission(permission) {
  const permissions = JSON.parse(localStorage.getItem('permissions') || '[]')
  return permissions.includes(permission)
}

export function hasAnyPermission(permissions) {
  return permissions.some(p => hasPermission(p))
}

export function isAdmin() {
  const roleType = parseInt(localStorage.getItem('roleType') || '0')
  return roleType === Role.ADMIN
}

export function getCurrentRole() {
  return parseInt(localStorage.getItem('roleType') || '0')
}



