import Vue from 'vue'
import Router from 'vue-router'

import ViewUI from 'view-design';
import { Permission, hasPermission } from '../config/permissions'
import store from '../store'



Vue.use(Router)
Vue.use(ViewUI);

const router = new Router({
    routes: [
        {
            path: '/',
            redirect: '/index'
        },
        {
            name:"index",
            path: '/index',
            component: require('@/views/index.vue').default,
            children: [
                {
                    path: '/',
                    redirect: '/dashboard'
                },
                {
                    name:"desc",
                    path: '/desc',
                    component: require('@/views/main/SoftDesc.vue').default,
                    meta: {
                        title: '软件介绍描述',
                        keepAlive: true
                    }
                },
                {
                    name:"dashboard",
                    path: '/dashboard',
                    component: require('@/views/main/Dashboard.vue').default,
                    meta: {
                        title: '数据大盘',
                        keepAlive: true,
                        permission: Permission.DASHBOARD_VIEW
                    }
                },
                {
                    name:"vip_list",
                    path: '/vip_list',
                    component: require('@/views/user/vip_list.vue').default,
                    meta: {
                        title: '激活码列表',
                        keepAlive: true,
                        permission: Permission.ADMIN_VIP_CODES_LIST
                    }
                },
                {
                    name:"user_list",
                    path: '/user_list',
                    component: require('@/views/user/user_list.vue').default,
                    meta: {
                        title: '用户列表',
                        keepAlive: true,
                        permission: Permission.ADMIN_USER_LIST
                    }
                },
                {
                    name:"user_rechaege",
                    path: '/user_rechaege',
                    component: require('@/views/order/user_rechaege.vue').default,
                    meta: {
                        title: '用户支付宝充值',
                        keepAlive: false,
                        permission: Permission.USER_RECHARGE
                    }
                },
                {
                    name:"user_vip",
                    path: '/user_vip',
                    component: require('@/views/order/user_vip.vue').default,
                    meta: {
                        title: '激活码充值',
                        keepAlive: false,
                        permission: Permission.USER_VIP_ACTIVATE
                    }
                },
                {
                    name:"user_bill",
                    path: '/user_bill',
                    component: require('@/views/order/user_bill.vue').default,
                    meta: {
                        title: '用户账单',
                        keepAlive: false,
                        permission: Permission.USER_BILL_VIEW
                    }
                },
                {
                    name:"user_activate_records",
                    path: '/user_activate_records',
                    component: require('@/views/order/user_activate_records.vue').default,
                    meta: {
                        title: '激活记录',
                        keepAlive: false,
                        permission: Permission.USER_VIP_RECORDS
                    }
                },
                {
                    name:"user_info",
                    path: '/user_info',
                    component: require('@/views/order/user_info.vue').default,
                    meta: {
                        title: '个人中心',
                        keepAlive: false,
                        permission: Permission.USER_INFO_EDIT
                    }
                },
                {
                    name:"login_devices",
                    path: '/login_devices',
                    component: require('@/views/order/login_devices.vue').default,
                    meta: {
                        title: '登录设备',
                        keepAlive: false,
                        permission: Permission.USER_LOGIN_DEVICES
                    }
                },
            ]
        },
        {
            name: 'login',
            path: '/login',
            component: require('@/views/user/login.vue').default,
            meta: ["登录页"]
        },
        {
            name: 'register',
            path: '/register',
            component: require('@/views/user/register.vue').default,
            meta: ["注册页"]
        },
        {
            name: 'forgot_pwd',
            path: '/forgot_pwd',
            component: require('@/views/user/forgot_pwd.vue').default,
            meta: ["注册页"]
        },
        {
            name: 'test',
            path: '/test',
            component: require('@/views/user/test.vue').default,
            meta: ["测试页"]
        }
    ]
})

const whiteList = ['login', 'register', 'forgot_pwd', 'test', 'desc']

router.beforeEach((to, from, next) => {
    const uid = localStorage.getItem('uid')
    const token = localStorage.getItem('token')
    
    if (uid && token) {
        if (to.name === 'login') {
            next({name: 'dashboard'})
        } else {
            if (to.meta && to.meta.permission) {
                const userPermissions = JSON.parse(localStorage.getItem('permissions') || '[]')
                if (userPermissions.length === 0) {
                    store.dispatch('getDate').then(() => {
                        const updatedPermissions = JSON.parse(localStorage.getItem('permissions') || '[]')
                        if (updatedPermissions.includes(to.meta.permission)) {
                            next()
                        } else {
                            ViewUI.Message.error('您没有访问该页面的权限')
                            next({name: 'dashboard'})
                        }
                    }).catch(() => {
                        next()
                    })
                } else if (userPermissions.includes(to.meta.permission)) {
                    next()
                } else {
                    ViewUI.Message.error('您没有访问该页面的权限')
                    next({name: 'dashboard'})
                }
            } else {
                next()
            }
        }
    } else {
        if (whiteList.includes(to.name)) {
            next()
        } else {
            next({name: 'login'})
        }
    }
})

export default router



